{
  "name": "MetaArchitect - AI Multi-Agent Studio",
  "description": "Ein Framework zur Simulation von MetaGPT-Workflows. Erstelle vollständige Software-Designs durch die Zusammenarbeit spezialisierter KI-Agenten.",
  "requestFramePermissions": []
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum AgentRole {
  PRODUCT_MANAGER = 'Product Manager',
  ARCHITECT = 'Software Architect',
  ENGINEER = 'Senior Engineer',
  QA = 'QA Engineer'
}

export interface AgentOutput {
  role: AgentRole;
  content: string;
  status: 'pending' | 'working' | 'completed' | 'error';
  artifacts?: {
    name: string;
    content: string;
    language: string;
  }[];
}

export interface ProjectState {
  id: string;
  idea: string;
  outputs: AgentOutput[];
  currentStep: number;
}

import { GoogleGenAI, Type } from "@google/genai";
import { AgentRole } from "./types";

const API_KEY = process.env.API_KEY || "";

export const runAgentTask = async (role: AgentRole, projectIdea: string, previousContext: string) => {
  const ai = new GoogleGenAI({ apiKey: API_KEY });

  const systemInstructions: Record<AgentRole, string> = {
    [AgentRole.PRODUCT_MANAGER]: `Du bist ein Product Manager. Deine Aufgabe ist es, aus einer Idee ein PRD (Product Requirements Document) zu erstellen. Definiere User Stories, Kern-Features und Erfolgskriterien. Antworte in Markdown.`,
    [AgentRole.ARCHITECT]: `Du bist ein Software Architect. Basierend auf dem PRD entwirfst du das System-Design. Erkläre die Tech-Stack Wahl, Datenbank-Schema und API-Struktur. Antworte in Markdown.`,
    [AgentRole.ENGINEER]: `Du bist ein Senior Engineer. Implementiere die Kern-Logik oder ein Boilerplate-Beispiel basierend auf dem Design. Gib validen Code aus.`,
    [AgentRole.QA]: `Du bist ein QA Engineer. Schreibe Testfälle und identifiziere potenzielle Edge-Cases oder Sicherheitsrisiken im Design und Code.`
  };

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: `
      Projekt-Idee: ${projectIdea}
      Bisheriger Kontext: ${previousContext}
      Deine spezifische Aufgabe als ${role}: Erstelle einen detaillierten Beitrag zum Projekt.
    `,
    config: {
      systemInstruction: systemInstructions[role],
      temperature: 0.7,
      thinkingConfig: { thinkingBudget: 4000 }
    }
  });

  return response.text;
};

import React from 'react';
import { AgentRole, AgentOutput } from '../types';

interface AgentProgressProps {
  outputs: AgentOutput[];
  currentStep: number;
}

export const AgentProgress: React.FC<AgentProgressProps> = ({ outputs, currentStep }) => {
  const roles = [
    AgentRole.PRODUCT_MANAGER,
    AgentRole.ARCHITECT,
    AgentRole.ENGINEER,
    AgentRole.QA
  ];

  return (
    <div className="flex flex-col space-y-4">
      {roles.map((role, index) => {
        const output = outputs.find(o => o.role === role);
        const isActive = index === currentStep;
        const isCompleted = index < currentStep;

        return (
          <div 
            key={role}
            className={`p-4 rounded-xl border transition-all duration-300 ${
              isActive 
                ? 'bg-blue-900/20 border-blue-500 shadow-[0_0_15px_rgba(59,130,246,0.2)]' 
                : isCompleted 
                  ? 'bg-emerald-900/10 border-emerald-500/50 opacity-80' 
                  : 'bg-slate-800/50 border-slate-700 opacity-50'
            }`}
          >
            <div className="flex items-center justify-between">
              <div className="flex items-center space-x-3">
                <div className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-bold ${
                  isActive ? 'bg-blue-500 text-white animate-pulse' : isCompleted ? 'bg-emerald-500 text-white' : 'bg-slate-700 text-slate-400'
                }`}>
                  {isCompleted ? '✓' : index + 1}
                </div>
                <div>
                  <h3 className="font-semibold text-slate-100">{role}</h3>
                  <p className="text-xs text-slate-400">
                    {isActive ? 'Generiere Dokumentation...' : isCompleted ? 'Abgeschlossen' : 'Wartet...'}
                  </p>
                </div>
              </div>
            </div>
          </div>
        );
      })}
    </div>
  );
};

import React, { useState, useCallback, useRef, useEffect } from 'react';
import { AgentRole, AgentOutput, ProjectState } from './types';
import { runAgentTask } from './geminiService';
import { AgentProgress } from './components/AgentProgress';
import { Layout, Play, Code2, Database, ShieldCheck, FileText, Send, Sparkles, AlertCircle, ExternalLink } from 'lucide-react';

const App: React.FC = () => {
  const [projectIdea, setProjectIdea] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [currentStep, setCurrentStep] = useState(-1);
  const [outputs, setOutputs] = useState<AgentOutput[]>([]);
  const [error, setError] = useState<string | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({
        top: scrollRef.current.scrollHeight,
        behavior: 'smooth'
      });
    }
  };

  useEffect(() => {
    scrollToBottom();
  }, [outputs]);

  const startWorkflow = async () => {
    if (!projectIdea.trim()) return;

    setIsProcessing(true);
    setError(null);
    setCurrentStep(0);
    setOutputs([]);

    const roles = [
      AgentRole.PRODUCT_MANAGER,
      AgentRole.ARCHITECT,
      AgentRole.ENGINEER,
      AgentRole.QA
    ];

    let context = "";

    try {
      for (let i = 0; i < roles.length; i++) {
        const role = roles[i];
        setCurrentStep(i);

        // Add optimistic pending state
        setOutputs(prev => [...prev, { role, content: '...', status: 'working' }]);

        const result = await runAgentTask(role, projectIdea, context);

        context += `\n\n--- [${role}] ---\n${result}`;

        setOutputs(prev => {
          const newOutputs = [...prev];
          newOutputs[i] = { role, content: result, status: 'completed' };
          return newOutputs;
        });
      }
      setCurrentStep(roles.length);
    } catch (err: any) {
      console.error(err);
      setError("Ein Fehler ist aufgetreten. Bitte überprüfe deine Verbindung.");
      setOutputs(prev => prev.map(o => o.status === 'working' ? { ...o, status: 'error' } : o));
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <div className="min-h-screen flex flex-col">
      {/* Header */}
      <header className="h-16 border-b border-slate-800 bg-slate-900/50 backdrop-blur-md flex items-center px-6 sticky top-0 z-50">
        <div className="flex items-center space-x-2">
          <div className="p-2 bg-blue-600 rounded-lg">
            <Sparkles className="text-white w-5 h-5" />
          </div>
          <h1 className="text-xl font-bold bg-gradient-to-r from-blue-400 to-emerald-400 bg-clip-text text-transparent">
            MetaArchitect Studio
          </h1>
        </div>
        <div className="ml-auto hidden md:flex space-x-6 text-sm font-medium text-slate-400">
          <a href="#" className="hover:text-white transition-colors">Framework</a>
          <a href="#" className="hover:text-white transition-colors">Agenten</a>
          <a href="#" className="hover:text-white transition-colors">Beispiele</a>
        </div>
      </header>

      <main className="flex-1 flex flex-col md:flex-row overflow-hidden">
        {/* Sidebar Controls */}
        <aside className="w-full md:w-80 border-r border-slate-800 p-6 space-y-8 overflow-y-auto bg-slate-900/30">
          <div>
            <h2 className="text-sm font-semibold text-slate-500 uppercase tracking-wider mb-4">Projekt-Einschätzung</h2>
            <div className="p-4 rounded-lg bg-blue-900/10 border border-blue-500/20 text-xs text-blue-200 leading-relaxed">
              <p className="mb-2"><strong>Analyse MetaGPT:</strong> MetaGPT ist ein revolutionärer Ansatz für Multi-Agenten-Kollaboration. Es transformiert LLMs von einfachen Chatbots in strukturierte Entwicklungsteams.</p>
              <p>Diese App nutzt das <strong>SOP-Prinzip</strong> (Standard Operating Procedures), um Software-Blueprints zu generieren.</p>
            </div>
          </div>

          <div className="space-y-4">
            <label className="block">
              <span className="text-sm font-medium text-slate-300">Software-Idee</span>
              <textarea 
                className="mt-2 w-full h-32 p-3 bg-slate-950 border border-slate-700 rounded-xl text-sm focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all resize-none"
                placeholder="Beschreibe deine App-Idee (z.B. 'Ein KI-gestütztes Task-Management System für Designer')"
                value={projectIdea}
                onChange={(e) => setProjectIdea(e.target.value)}
                disabled={isProcessing}
              />
            </label>
            <button
              onClick={startWorkflow}
              disabled={isProcessing || !projectIdea.trim()}
              className="w-full py-3 bg-blue-600 hover:bg-blue-500 disabled:bg-slate-700 disabled:cursor-not-allowed text-white rounded-xl font-semibold flex items-center justify-center space-x-2 transition-all shadow-lg shadow-blue-900/20"
            >
              {isProcessing ? (
                <div className="animate-spin rounded-full h-5 w-5 border-2 border-white/30 border-t-white" />
              ) : (
                <>
                  <Play className="w-4 h-4" />
                  <span>Entwicklung starten</span>
                </>
              )}
            </button>
          </div>

          <div>
            <h2 className="text-sm font-semibold text-slate-500 uppercase tracking-wider mb-4">Workflow-Status</h2>
            <AgentProgress outputs={outputs} currentStep={currentStep} />
          </div>
        </aside>

        {/* Content Area */}
        <section className="flex-1 bg-slate-950/50 flex flex-col overflow-hidden relative">
          <div 
            ref={scrollRef}
            className="flex-1 overflow-y-auto p-6 md:p-10 space-y-12"
          >
            {outputs.length === 0 && !isProcessing && (
              <div className="h-full flex flex-col items-center justify-center text-center max-w-xl mx-auto space-y-6">
                <div className="w-20 h-20 bg-slate-900 rounded-3xl flex items-center justify-center border border-slate-800">
                  <Layout className="w-10 h-10 text-slate-500" />
                </div>
                <div className="space-y-2">
                  <h3 className="text-2xl font-bold text-slate-100">Bereit für den Blueprint?</h3>
                  <p className="text-slate-400">Gib eine Idee in der Seitenleiste ein, um den MetaGPT-Workflow zu simulieren. Unsere Agenten erstellen PRDs, Architekturpläne und Code-Beispiele.</p>
                </div>
                <div className="grid grid-cols-2 gap-4 w-full">
                  <button onClick={() => setProjectIdea("Fitness Tracker App mit KI-Coaching")} className="p-3 bg-slate-900 border border-slate-800 rounded-lg text-xs text-slate-400 hover:bg-slate-800 transition-colors">
                    Fitness App ➔
                  </button>
                  <button onClick={() => setProjectIdea("SaaS Dashboard für Solar-Energie Monitoring")} className="p-3 bg-slate-900 border border-slate-800 rounded-lg text-xs text-slate-400 hover:bg-slate-800 transition-colors">
                    Solar Dashboard ➔
                  </button>
                </div>
              </div>
            )}

            {outputs.map((output, idx) => (
              <div 
                key={idx} 
                className="animate-in fade-in slide-in-from-bottom-4 duration-500"
              >
                <div className="flex items-center space-x-3 mb-6">
                  <div className={`p-2 rounded-lg ${
                    output.role === AgentRole.PRODUCT_MANAGER ? 'bg-purple-900/30 text-purple-400' :
                    output.role === AgentRole.ARCHITECT ? 'bg-amber-900/30 text-amber-400' :
                    output.role === AgentRole.ENGINEER ? 'bg-emerald-900/30 text-emerald-400' :
                    'bg-rose-900/30 text-rose-400'
                  }`}>
                    {output.role === AgentRole.PRODUCT_MANAGER && <FileText className="w-5 h-5" />}
                    {output.role === AgentRole.ARCHITECT && <Layout className="w-5 h-5" />}
                    {output.role === AgentRole.ENGINEER && <Code2 className="w-5 h-5" />}
                    {output.role === AgentRole.QA && <ShieldCheck className="w-5 h-5" />}
                  </div>
                  <h2 className="text-lg font-bold text-slate-100">{output.role} Report</h2>
                </div>

                <div className={`prose prose-invert max-w-none p-6 rounded-2xl border ${
                  output.status === 'working' ? 'bg-slate-900/50 border-slate-700 animate-pulse' : 'bg-slate-900 border-slate-800'
                }`}>
                  {output.status === 'working' ? (
                    <div className="space-y-4">
                      <div className="h-4 bg-slate-800 rounded w-3/4"></div>
                      <div className="h-4 bg-slate-800 rounded w-1/2"></div>
                      <div className="h-4 bg-slate-800 rounded w-5/6"></div>
                    </div>
                  ) : (
                    <div className="whitespace-pre-wrap font-mono text-sm leading-relaxed text-slate-300">
                      {output.content}
                    </div>
                  )}
                </div>
              </div>
            ))}

            {error && (
              <div className="flex items-center space-x-2 p-4 bg-rose-900/20 border border-rose-500/30 rounded-xl text-rose-400 text-sm">
                <AlertCircle className="w-4 h-4" />
                <span>{error}</span>
              </div>
            )}
          </div>

          {/* Prompt bar (sticky at bottom of area) */}
          <div className="p-6 border-t border-slate-800 bg-slate-950/80 backdrop-blur-md">
            <div className="max-w-3xl mx-auto flex items-center space-x-4">
              <div className="text-xs text-slate-500 flex items-center space-x-2">
                <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
                <span>Gemini 3 Pro Engine aktiv</span>
              </div>
              <div className="flex-1"></div>
              <button className="text-xs text-slate-400 hover:text-white flex items-center space-x-1">
                <ExternalLink className="w-3 h-3" />
                <span>MetaGPT Repo ansehen</span>
              </button>
            </div>
          </div>
        </section>
      </main>
    </div>
  );
};

export default App;

export enum AgentRole {
  PRODUCT_MANAGER = 'Product Manager',
  ARCHITECT = 'Software Architect',
  ENGINEER = 'Senior Engineer',
  QA = 'QA Engineer'
}

export interface AgentOutput {
  role: AgentRole;
  content: string;
  status: 'pending' | 'working' | 'completed' | 'error';
  code?: string; // Extracted runnable code
}

export interface ProjectState {
  id: string;
  idea: string;
  outputs: AgentOutput[];
  currentStep: number;
}

import { GoogleGenAI } from "@google/genai";
import { AgentRole } from "./types";

const API_KEY = process.env.API_KEY || "";

export const runAgentTask = async (role: AgentRole, projectIdea: string, previousContext: string) => {
  const ai = new GoogleGenAI({ apiKey: API_KEY });

  const systemInstructions: Record<AgentRole, string> = {
    [AgentRole.PRODUCT_MANAGER]: `Du bist ein Product Manager. Erstelle ein PRD in Markdown. Fokus: User Stories und Features.`,
    [AgentRole.ARCHITECT]: `Du bist ein Software Architect. Erstelle ein technisches Design in Markdown. Fokus: Datenfluss und Komponenten-Struktur.`,
    [AgentRole.ENGINEER]: `Du bist ein Senior Engineer. DEINE AUFGABE: Erstelle einen funktionalen Prototyp als EINZELNE HTML-DATEI (inklusive CSS und JS in <style> und <script> Tags). Verwende Tailwind CSS via CDN falls nötig. Der Code muss in einem Markdown-Code-Block stehen. Er soll die Kernidee von "${projectIdea}" interaktiv demonstrieren.`,
    [AgentRole.QA]: `Du bist ein QA Engineer. Analysiere den Code und das Design. Erstelle einen Testbericht in Markdown.`
  };

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: `
      Projekt-Idee: ${projectIdea}
      Bisherige Dokumentation: ${previousContext}
      Deine Aufgabe als ${role}: Erstelle deinen Beitrag. Wenn du der ENGINEER bist, liefere unbedingt lauffähigen HTML/JS Code in einem Codeblock.
    `,
    config: {
      systemInstruction: systemInstructions[role],
      temperature: 0.4, // Niedrigere Temperatur für präziseren Code
      thinkingConfig: { thinkingBudget: 4000 }
    }
  });

  return response.text;
};

export const extractCode = (markdown: string): string | undefined => {
  const codeBlockRegex = /```html\n([\s\S]*?)```/i;
  const match = markdown.match(codeBlockRegex);
  if (match && match[1]) return match[1];

  // Fallback for generic code blocks if html is not specified
  const genericMatch = /```\n([\s\S]*?)```/.match(markdown);
  return genericMatch ? genericMatch[1] : undefined;
};

import React from 'react';

interface LivePreviewProps {
  code: string;
}

export const LivePreview: React.FC<LivePreviewProps> = ({ code }) => {
  if (!code) {
    return (
      <div className="h-full flex items-center justify-center text-slate-500 italic">
        Warte auf Code-Generierung durch den Engineer...
      </div>
    );
  }

  return (
    <div className="h-full w-full bg-white rounded-xl overflow-hidden shadow-2xl border border-slate-800">
      <iframe
        title="Prototype Preview"
        srcDoc={code}
        className="w-full h-full border-none"
        sandbox="allow-scripts allow-forms allow-modals"
      />
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { AgentRole, AgentOutput } from './types';
import { runAgentTask, extractCode } from './geminiService';
import { AgentProgress } from './components/AgentProgress';
import { LivePreview } from './components/LivePreview';
import { 
  Layout, Play, Code2, ShieldCheck, FileText, 
  Sparkles, AlertCircle, Eye, FileJson, Terminal 
} from 'lucide-react';

const App: React.FC = () => {
  const [projectIdea, setProjectIdea] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [currentStep, setCurrentStep] = useState(-1);
  const [outputs, setOutputs] = useState<AgentOutput[]>([]);
  const [activeTab, setActiveTab] = useState<'docs' | 'preview'>('docs');
  const [error, setError] = useState<string | null>(null);
  const [generatedCode, setGeneratedCode] = useState<string>('');
  const scrollRef = useRef<HTMLDivElement>(null);

  const startWorkflow = async () => {
    if (!projectIdea.trim()) return;

    setIsProcessing(true);
    setError(null);
    setCurrentStep(0);
    setOutputs([]);
    setGeneratedCode('');
    setActiveTab('docs');

    const roles = [
      AgentRole.PRODUCT_MANAGER,
      AgentRole.ARCHITECT,
      AgentRole.ENGINEER,
      AgentRole.QA
    ];

    let context = "";

    try {
      for (let i = 0; i < roles.length; i++) {
        const role = roles[i];
        setCurrentStep(i);

        setOutputs(prev => [...prev, { role, content: '...', status: 'working' }]);

        const result = await runAgentTask(role, projectIdea, context);

        // Extract code if it's the engineer
        if (role === AgentRole.ENGINEER) {
          const code = extractCode(result);
          if (code) setGeneratedCode(code);
        }

        context += `\n\n--- [${role}] ---\n${result}`;

        setOutputs(prev => {
          const newOutputs = [...prev];
          newOutputs[i] = { role, content: result, status: 'completed', code: role === AgentRole.ENGINEER ? extractCode(result) : undefined };
          return newOutputs;
        });
      }
      setCurrentStep(roles.length);
    } catch (err: any) {
      console.error(err);
      setError("Workflow unterbrochen. Bitte erneut versuchen.");
      setOutputs(prev => prev.map(o => o.status === 'working' ? { ...o, status: 'error' } : o));
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#0b0f1a] text-slate-200">
      {/* Header */}
      <header className="h-14 border-b border-slate-800 bg-slate-900/80 backdrop-blur-md flex items-center px-4 sticky top-0 z-50">
        <div className="flex items-center space-x-2">
          <div className="p-1.5 bg-indigo-600 rounded-lg shadow-lg shadow-indigo-500/20">
            <Terminal className="text-white w-4 h-4" />
          </div>
          <h1 className="text-sm font-bold tracking-tight text-white uppercase">
            MetaArchitect <span className="text-indigo-400">v2.0</span>
          </h1>
        </div>

        <div className="mx-auto flex bg-slate-800/50 p-1 rounded-lg border border-slate-700">
          <button 
            onClick={() => setActiveTab('docs')}
            className={`px-4 py-1.5 text-xs font-medium rounded-md transition-all flex items-center space-x-2 ${activeTab === 'docs' ? 'bg-slate-700 text-white shadow-sm' : 'text-slate-400 hover:text-slate-200'}`}
          >
            <FileJson className="w-3.5 h-3.5" />
            <span>Reports</span>
          </button>
          <button 
            onClick={() => setActiveTab('preview')}
            className={`px-4 py-1.5 text-xs font-medium rounded-md transition-all flex items-center space-x-2 ${activeTab === 'preview' ? 'bg-indigo-600 text-white shadow-sm' : 'text-slate-400 hover:text-slate-200'}`}
          >
            <Eye className="w-3.5 h-3.5" />
            <span>Live App</span>
          </button>
        </div>

        <div className="flex items-center space-x-3">
          <div className="px-2 py-1 rounded bg-slate-800 border border-slate-700 text-[10px] text-slate-400 font-mono">
            API: GEMINI-3-PRO
          </div>
        </div>
      </header>

      <main className="flex-1 flex overflow-hidden">
        {/* Sidebar */}
        <aside className="w-72 border-r border-slate-800 bg-[#0f1422] flex flex-col">
          <div className="p-5 space-y-6">
            <div className="space-y-2">
              <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Projekt-Konzept</label>
              <textarea 
                className="w-full h-32 p-3 bg-slate-900/50 border border-slate-800 rounded-lg text-sm text-slate-200 focus:ring-1 focus:ring-indigo-500 outline-none transition-all resize-none placeholder:text-slate-600"
                placeholder="Beschreibe die Software..."
                value={projectIdea}
                onChange={(e) => setProjectIdea(e.target.value)}
                disabled={isProcessing}
              />
              <button
                onClick={startWorkflow}
                disabled={isProcessing || !projectIdea.trim()}
                className="w-full py-2.5 bg-indigo-600 hover:bg-indigo-500 disabled:bg-slate-800 text-white rounded-lg font-bold text-xs flex items-center justify-center space-x-2 transition-all shadow-lg shadow-indigo-500/10"
              >
                {isProcessing ? <div className="animate-spin h-3 w-3 border-2 border-white/20 border-t-white rounded-full" /> : <Play className="w-3.5 h-3.5 fill-current" />}
                <span>{isProcessing ? 'Agenten arbeiten...' : 'Blueprint erstellen'}</span>
              </button>
            </div>

            <div className="pt-4 border-t border-slate-800">
              <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-4 block">Multi-Agent Workflow</label>
              <AgentProgress outputs={outputs} currentStep={currentStep} />
            </div>
          </div>
        </aside>

        {/* Content */}
        <section className="flex-1 bg-[#0b0f1a] overflow-hidden">
          {activeTab === 'docs' ? (
            <div ref={scrollRef} className="h-full overflow-y-auto p-8 space-y-10 scroll-smooth">
              {outputs.length === 0 && !isProcessing && (
                <div className="h-full flex flex-col items-center justify-center space-y-4">
                  <div className="w-16 h-16 bg-slate-900 border border-slate-800 rounded-2xl flex items-center justify-center">
                    <Sparkles className="w-8 h-8 text-indigo-500/50" />
                  </div>
                  <h2 className="text-xl font-medium text-slate-300">Bereit für die Architektur?</h2>
                  <p className="text-slate-500 text-sm max-w-sm text-center">Gib eine Idee ein. Die Agenten-Kette simuliert den MetaGPT Prozess von der Planung bis zum Test.</p>
                </div>
              )}

              {outputs.map((output, idx) => (
                <article key={idx} className="max-w-4xl mx-auto animate-in fade-in slide-in-from-bottom-2 duration-700">
                  <div className="flex items-center space-x-3 mb-4">
                    <div className="w-8 h-8 rounded-lg bg-slate-900 border border-slate-800 flex items-center justify-center">
                      {output.role === AgentRole.PRODUCT_MANAGER && <FileText className="w-4 h-4 text-purple-400" />}
                      {output.role === AgentRole.ARCHITECT && <Layout className="w-4 h-4 text-amber-400" />}
                      {output.role === AgentRole.ENGINEER && <Code2 className="w-4 h-4 text-emerald-400" />}
                      {output.role === AgentRole.QA && <ShieldCheck className="w-4 h-4 text-rose-400" />}
                    </div>
                    <h3 className="text-sm font-bold text-slate-200">{output.role} Output</h3>
                  </div>
                  <div className={`p-6 rounded-xl border border-slate-800 bg-[#0f1422] shadow-sm font-mono text-sm leading-relaxed ${output.status === 'working' ? 'animate-pulse border-indigo-500/30' : ''}`}>
                    {output.status === 'working' ? (
                      <div className="space-y-2">
                        <div className="h-2 bg-slate-800 rounded w-full"></div>
                        <div className="h-2 bg-slate-800 rounded w-4/5"></div>
                      </div>
                    ) : (
                      <div className="whitespace-pre-wrap text-slate-400">{output.content}</div>
                    )}
                  </div>
                </article>
              ))}

              {error && (
                <div className="max-w-4xl mx-auto p-4 bg-rose-500/10 border border-rose-500/20 rounded-lg flex items-center space-x-2 text-rose-400 text-xs">
                  <AlertCircle className="w-4 h-4" />
                  <span>{error}</span>
                </div>
              )}
            </div>
          ) : (
            <div className="h-full p-4 flex flex-col">
              <div className="flex-1 rounded-xl overflow-hidden bg-white shadow-2xl relative">
                {!generatedCode && !isProcessing && (
                  <div className="absolute inset-0 flex flex-col items-center justify-center bg-slate-900 text-slate-500 space-y-4">
                    <Eye className="w-12 h-12 opacity-20" />
                    <p>Noch kein lauffähiger Code vorhanden.</p>
                  </div>
                )}
                <LivePreview code={generatedCode} />
              </div>
            </div>
          )}
        </section>
      </main>
    </div>
  );
};

export default App;

