  projectIdea: string, 
  previousContext: string, 
  refinementFeedback?: string,
  previousOutput?: string
) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const isRefining = !!refinementFeedback;

  const systemInstructions: Record<AgentRole, string> = {
    [AgentRole.PRODUCT_MANAGER]: `Du bist ein Product Manager. ${isRefining ? 'ÜBERARBEITE das bestehende PRD basierend auf diesem Feedback: ' + refinementFeedback : 'Erstelle ein PRD in Markdown.'} Fokus: User Stories und Features.`,
    [AgentRole.ARCHITECT]: `Du bist ein Software Architect. ${isRefining ? 'PASSE das System-Design an basierend auf dem neuen PRD und diesem Feedback: ' + refinementFeedback : 'Erstelle ein technisches Design in Markdown.'} Fokus: Datenfluss und Komponenten-Struktur.`,
    [AgentRole.ENGINEER]: `Du bist ein Senior Engineer. DEINE AUFGABE: Erstelle einen funktionalen Prototyp als EINZELNE HTML-DATEI. ${isRefining ? 'AKTUALISIERE den bestehenden Code basierend auf diesem Feedback: ' + refinementFeedback : 'Implementiere die Kernidee.'} Verwende Tailwind CSS via CDN. Der Code MUSS in einem Markdown-Code-Block ( \`\`\`html ) stehen.`,
    [AgentRole.QA]: `Du bist ein QA Engineer. ${isRefining ? 'Führe ein Regression-Testing durch und prüfe, ob das Feedback umgesetzt wurde: ' + refinementFeedback : 'Analysiere den Code und das Design.'} Erstelle einen Testbericht.`
  };

  const prompt = isRefining 
    ? `PROJEKT: ${projectIdea}
       FEEDBACK ZUR VERBESSERUNG: ${refinementFeedback}
       DEIN VORHERIGER OUTPUT: ${previousOutput}
       KONTEXT DER ANDEREN AGENTEN: ${previousContext}
       Bitte überarbeite deine Arbeit entsprechend.`
    : `PROJEKT: ${projectIdea}
       BISHERIGER KONTEXT: ${previousContext}
       Erstelle deinen Beitrag als ${role}.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: prompt,
    config: {
      systemInstruction: systemInstructions[role],
      temperature: 0.4,
      thinkingConfig: { thinkingBudget: 4000 }
    }
  });

  return response.text;
};

